# settings.py (psycopg 3)
import psycopg
DATABASES["default"]["OPTIONS"] = {"isolation_level": psycopg.IsolationLevel.SERIALIZABLE}

# service layer
from django.db import transaction, OperationalError
import psycopg.errors as pe

def with_retry(fn, attempts=3):
    for i in range(attempts):
        try:
            with transaction.atomic():
                return fn()
        except OperationalError as e:
            if isinstance(e.__cause__, pe.SerializationFailure) and i < attempts - 1:
                continue
            raise

