SHARDS = ["shard0", "shard1", "shard2", "shard3"]

def shard_for(customer_id: int) -> str:
    return SHARDS[customer_id % len(SHARDS)]    # naive; use consistent hashing in practice

class ShardRouter:
    def db_for_read(self, model, **hints):
        inst = hints.get("instance")
        return shard_for(inst.customer_id) if inst else "default"
    db_for_write = db_for_read

Order.objects.using(shard_for(cid)).filter(customer_id=cid)

